import math
n = int(input())
for i in range(n):
	m = int(input())
	nums = [int(i) for i in input().split()]
	highest = nums[0]
	mostDiff = 0
	for j in range(len(nums)):
		if highest - nums[j] > mostDiff:
			mostDiff = highest - nums[j]
		if nums[j] > highest:
			highest = nums[j]
	if mostDiff == 0:
		print(0)
	else:
		print(int(math.log(mostDiff, 2) + 1))
